from urllib.parse import urljoin

async def act(page):
    """
    Steps:
    1. Locate the row that contains the cell with the exact text "404 Not Found" using accessibility selectors.
    2. Extract an edit URL from the row or title cell (commonly via an onclick containing setLocation('...')).
       Navigate to that edit URL using page.goto (so the click that would navigate isn't required and isn't the last action).
    3. On the edit page, locate the "Page Title" textbox and fill it with the requested new title.
    4. Click the Save button using accessible role/name selectors and wait for the save to complete.

    Note on knowledge-base helper functions: there are no applicable helper functions in the provided knowledge base, so none are used.
    """

    new_title = "Bruh bro you clicked the wrong page"

