    await page.wait_for_load_state("domcontentloaded")
    await asyncio.sleep(0.5)

    # Step 1: find the row that contains the cell named "404 Not Found"
    rows = page.get_by_role("row").filter(has=page.get_by_role("cell", name="404 Not Found"))
    if await rows.count() == 0:
        raise RuntimeError('Could not find a row containing a cell with the name "404 Not Found"')

    row = rows.first

    # Step 2: attempt to extract an edit URL from onclick attributes or links in the row
    edit_href = None

    # Try onclick on the row
    onclick_attr = await row.get_attribute("onclick")
    if onclick_attr:
        m = re.search(r"setLocation\(['\"]([^'\"]+)['\"]\)", onclick_attr)
        if m:
            edit_href = m.group(1)
        else:
            # fallback: any quoted relative path inside the attribute
            m2 = re.search(r"['\"](\/[^'\"]+)['\"]", onclick_attr)
            if m2:
                edit_href = m2.group(1)

    # If not found on the row, try the title cell's onclick attribute
    if not edit_href:
        title_cell = row.get_by_role("cell", name="404 Not Found")
        if await title_cell.count() > 0:
            onclick_cell = await title_cell.first.get_attribute("onclick")
            if onclick_cell:
                m3 = re.search(r"setLocation\(['\"]([^'\"]+)['\"]\)", onclick_cell)
                if m3:
                    edit_href = m3.group(1)
                else:
                    m4 = re.search(r"['\"](\/[^'\"]+)['\"]", onclick_cell)
                    if m4:
