    if not edit_href:
        links_in_row = row.get_by_role("link")
        if await links_in_row.count() > 0:
            # prefer link with indicative path; otherwise use the first href found
            href_found = None
            for i in range(min(20, await links_in_row.count())):
                href = await links_in_row.nth(i).get_attribute("href")
                if href:
